function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function stagePlan(minutes){
  minutes=parseInt(minutes,10)||40;
  if(minutes>=80){ return [['导入',5],['新授讲授',35],['实践练习',25],['小结',10],['作业布置',5]]; }
  return [['导入',5],['新授讲授',18],['课堂练习',10],['小结',5],['作业布置',2]];
}
function stageHint(stage, topic){
  if(stage.indexOf('导入')>=0) return '情境或问题导入，引出《'+topic+'》主题';
  if(stage.indexOf('新授')>=0) return '讲解核心概念，配合示例逐步演示';
  if(stage.indexOf('练习')>=0) return '随堂分层练习，即时反馈与纠错';
  if(stage.indexOf('小结')>=0) return '师生共同梳理本课知识要点';
  return '布置分层作业，兼顾巩固与拓展';
}
function buildLessonPlan(o){
  o=o||{};
  var subject=String(o.subject||'通用').trim()||'通用';
  var grade=String(o.grade||'初中').trim()||'初中';
  var minutes=parseInt(o.minutes,10)||40;
  var topic=String(o.topic||'').trim()||'（待填写课题）';
  var goals=splitLines(o.goals);
  if(!goals.length) goals=['（待补充教学目标）'];
  var key=String(o.key||'').trim();
  var diff=String(o.diff||'').trim();
  var stages=stagePlan(minutes);
  var lines=[];
  lines.push('# 教案：'+subject+'《'+topic+'》');
  lines.push('');
  lines.push('## 一、基本信息');
  lines.push('- 学科：'+subject);
  lines.push('- 学段：'+grade);
  lines.push('- 课时：'+minutes+' 分钟');
  lines.push('');
  lines.push('## 二、教学目标');
  goals.forEach(function(g,i){ lines.push((i+1)+'. '+g); });
  lines.push('');
  lines.push('## 三、教学重难点');
  lines.push('- 重点：'+(key||'围绕《'+topic+'》的核心概念与典型方法'));
  lines.push('- 难点：'+(diff||'概念的理解迁移与综合应用'));
  lines.push('');
  lines.push('## 四、教学过程');
  stages.forEach(function(s,i){
    lines.push('### '+(i+1)+'. '+s[0]+'（约 '+s[1]+' 分钟）');
    lines.push('- '+stageHint(s[0], topic));
    lines.push('');
  });
  lines.push('## 五、板书设计');
  lines.push('```');
  lines.push(topic);
  lines.push('├── 核心概念');
  lines.push('└── 典型例题 / 案例');
  lines.push('```');
  lines.push('');
  lines.push('## 六、教学反思');
  lines.push('（课后填写：目标达成情况 / 学生参与度 / 待改进点）');
  return {title:subject+'《'+topic+'》教案', minutes:minutes, stageCount:stages.length,
          goalCount:goals.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, stagePlan:stagePlan, buildLessonPlan:buildLessonPlan};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LessonPlanForgePure = EXPORTS; }
